#!/usr/bin/env python3
"""Generate the DRY mixed-integral ULong2048 operator surface."""
from __future__ import annotations

import argparse
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
TARGET = ROOT / "Ricis.Numerics" / "ULong2048.IntegralOperators.generated.cs"
TEST_TARGET = ROOT / "Ricis.Numerics" / "Ricis.Numerics.UnitTests" / "ULong2048IntegralOperators.generated.cs"

UNSIGNED = ["byte", "ushort", "uint", "ulong", "nuint", "UInt128"]
