TEST_HEADER = """// <auto-generated />
// Generated by scripts/generate_ulong2048_integral_operators.py. Do not hand edit.
#nullable enable

using System.Numerics;
using Microsoft.VisualStudio.TestTools.UnitTesting;

namespace Ricis.Numerics.UnitTests;

[TestClass]
public sealed class ULong2048IntegralOperatorsGeneratedSuite
{
    private static readonly BigInteger Modulus = BigInteger.One << 2048;
    private static readonly ULong2048 Value = ULong2048.FromBigInteger((BigInteger.One << 160) + 12345);
    private static readonly BigInteger ValueBigInteger = Value.ToBigInteger();
    private static BigInteger B(ULong2048 value) => value.ToBigInteger();
    private static BigInteger Wrap(BigInteger value)
    {
        value %= Modulus;
        return value.Sign < 0 ? value + Modulus : value;
    }

"""


def unsigned_literal(t: str) -> str:
    return {
        "byte": "(byte)7", "ushort": "(ushort)7", "uint": "7u", "ulong": "7ul",
        "nuint": "(nuint)7", "UInt128": "(UInt128)7",
    }[t]


def signed_literal(t: str, value: int) -> str:
    raw = str(value)
    return {
        "sbyte": f"(sbyte){raw}", "short": f"(short){raw}", "int": raw, "long": f"{raw}L",
        "nint": f"(nint)({raw})", "Int128": f"(Int128)({raw})",
    }[t]


def unsigned_test(t: str, ordinal: int) -> str:
    literal = unsigned_literal(t)
    return f"""    [TestMethod(\"U2048-INTEGRAL-U{ordinal:02}: {t} symmetric arithmetic bitwise comparison checked and shifts\")]
    public void Unsigned_{t}_Operators()
    {{
        {t} operand = {literal};
        var operandBigInteger = new BigInteger(7);
        Assert.AreEqual(Wrap(ValueBigInteger + operandBigInteger), B(Value + operand));
        Assert.AreEqual(Wrap(operandBigInteger + ValueBigInteger), B(operand + Value));
        Assert.AreEqual(Wrap(ValueBigInteger - operandBigInteger), B(Value - operand));
        Assert.AreEqual(Wrap(operandBigInteger - ValueBigInteger), B(operand - Value));
        Assert.AreEqual(Wrap(ValueBigInteger * operandBigInteger), B(Value * operand));
        Assert.AreEqual(Wrap(operandBigInteger * ValueBigInteger), B(operand * Value));
        Assert.AreEqual(ValueBigInteger / operandBigInteger, B(Value / operand));
        Assert.AreEqual(operandBigInteger / ValueBigInteger, B(operand / Value));
        Assert.AreEqual(ValueBigInteger % operandBigInteger, B(Value % operand));
        Assert.AreEqual(operandBigInteger % ValueBigInteger, B(operand % Value));
        Assert.AreEqual(ValueBigInteger & operandBigInteger, B(Value & operand));
        Assert.AreEqual(operandBigInteger & ValueBigInteger, B(operand & Value));
        Assert.AreEqual(ValueBigInteger | operandBigInteger, B(Value | operand));
        Assert.AreEqual(operandBigInteger | ValueBigInteger, B(operand | Value));
        Assert.AreEqual(ValueBigInteger ^ operandBigInteger, B(Value ^ operand));
        Assert.AreEqual(operandBigInteger ^ ValueBigInteger, B(operand ^ Value));
        Assert.IsTrue(Value > operand && operand < Value && Value != operand && operand != Value);
        Assert.AreEqual(Value << 7, Value << operand);
        Assert.AreEqual(Value >> 7, Value >> operand);
        Assert.AreEqual(Value >>> 7, Value >>> operand);
        Assert.ThrowsException<OverflowException>(() => _ = checked(ULong2048.MaxValue + operand));
        Assert.ThrowsException<OverflowException>(() => _ = checked(ULong2048.Zero - operand));
        Assert.ThrowsException<OverflowException>(() => _ = checked(ULong2048.MaxValue * operand));
    }}

"""


def signed_test(t: str, ordinal: int) -> str:
    positive = signed_literal(t, 7)
    negative = signed_literal(t, -7)
    return f"""    [TestMethod(\"U2048-INTEGRAL-S{ordinal:02}: {t} exact signed arithmetic bitwise comparison and shifts\")]
    public void Signed_{t}_Operators()
    {{
        {t} positive = {positive};
        {t} negative = {negative};
        var positiveBigInteger = new BigInteger(7);
        var negativeBigInteger = new BigInteger(-7);
        Assert.AreEqual(ValueBigInteger + positiveBigInteger, Value + positive);
        Assert.AreEqual(positiveBigInteger + ValueBigInteger, positive + Value);
        Assert.AreEqual(ValueBigInteger - positiveBigInteger, Value - positive);
        Assert.AreEqual(positiveBigInteger - ValueBigInteger, positive - Value);
        Assert.AreEqual(ValueBigInteger * negativeBigInteger, Value * negative);
        Assert.AreEqual(negativeBigInteger * ValueBigInteger, negative * Value);
        Assert.AreEqual(ValueBigInteger / negativeBigInteger, Value / negative);
        Assert.AreEqual(negativeBigInteger / ValueBigInteger, negative / Value);
        Assert.AreEqual(ValueBigInteger % negativeBigInteger, Value % negative);
        Assert.AreEqual(negativeBigInteger % ValueBigInteger, negative % Value);
        Assert.AreEqual(ValueBigInteger & negativeBigInteger, Value & negative);
        Assert.AreEqual(negativeBigInteger & ValueBigInteger, negative & Value);
        Assert.AreEqual(ValueBigInteger | negativeBigInteger, Value | negative);
        Assert.AreEqual(negativeBigInteger | ValueBigInteger, negative | Value);
        Assert.AreEqual(ValueBigInteger ^ negativeBigInteger, Value ^ negative);
        Assert.AreEqual(negativeBigInteger ^ ValueBigInteger, negative ^ Value);
        Assert.IsTrue(Value > negative && negative < Value && Value != negative && negative != Value);
        Assert.AreEqual(Value << 7, Value << positive);
        Assert.AreEqual(Value >> 7, Value >> positive);
        Assert.AreEqual(Value >>> 7, Value >>> positive);
        Assert.AreEqual(Value >> 7, Value << negative);
    }}

"""


def render_tests() -> str:
    body = TEST_HEADER
    for index, t in enumerate(UNSIGNED, start=1):
        body += unsigned_test(t, index)
    for index, t in enumerate(SIGNED, start=1):
        body += signed_test(t, index)
    return body + "}\n"


def render() -> str:
    body = HEADER
    for t in UNSIGNED:
        body += unsigned_block(t)
    for t in SIGNED:
        body += signed_block(t)
    body += "}\n"
    return body


def main() -> int:
    parser = argparse.ArgumentParser()
    parser.add_argument("--check", action="store_true")
    args = parser.parse_args()
    generated = render()
    generated_tests = render_tests()
    if args.check:
        if not TARGET.exists() or TARGET.read_text() != generated or not TEST_TARGET.exists() or TEST_TARGET.read_text() != generated_tests:
            print("ULONG2048_INTEGRAL_OPERATORS_STALE")
            return 1
        print("ULONG2048_INTEGRAL_OPERATORS_VERIFY_PASS")
        return 0
    TARGET.write_text(generated)
    TEST_TARGET.write_text(generated_tests)
    print("ULONG2048_INTEGRAL_OPERATORS_GENERATED")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
